package com.cpf.starter.quartz;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.scheduler.quartz") public class CpfQuartzProperties {private boolean enabled;private String instanceName="CPF_QUARTZ";private boolean clustered=true;private int threadCount=10;private long misfireThreshold=60000;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getInstanceName(){return instanceName;}public void setInstanceName(String v){instanceName=v;}public boolean isClustered(){return clustered;}public void setClustered(boolean v){clustered=v;}public int getThreadCount(){return threadCount;}public void setThreadCount(int v){threadCount=v;}public long getMisfireThreshold(){return misfireThreshold;}public void setMisfireThreshold(long v){misfireThreshold=v;}public void validate(){if(!enabled)return;if(threadCount<1||threadCount>200||misfireThreshold<1000)throw new IllegalStateException("invalid Quartz limits");}}
